<?php
declare(strict_types=1);
ini_set('session.cookie_httponly','1');ini_set('session.use_strict_mode','1');if(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')ini_set('session.cookie_secure','1');session_start();require __DIR__.'/app.php';
$action=(string)($_GET['action']??'home');$msg='';$err='';$data=null;
try{
 if($action==='connect'&&$_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();[$o,$rp,$u]=parseRepo((string)$_POST['url']);$_SESSION['repo']=['owner'=>$o,'repo'=>$rp,'url'=>$u,'branch'=>safeBranch((string)($_POST['branch']??'main')),'username'=>trim((string)($_POST['username']??'')),'password'=>(string)($_POST['password']??''),'token'=>(string)($_POST['token']??'')];(new GH($_SESSION['repo']))->repo();$msg='Repositorio conectado.';
 }elseif($action==='disconnect'){session_unset();session_regenerate_id(true);$msg='Sessao removida.';
 }elseif($action==='browse'){$r=sourceRepo();$data=(new GH($r))->contents((string)($_GET['path']??''));
 }elseif($action==='clone'&&$_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$r=sourceRepo();$gh=new GH($r);$tree=$gh->tree();if(!empty($tree['truncated']))throw new RuntimeException('Arvore truncada.');$files=array_values(array_filter($tree['tree']??[],function($x){return($x['type']??'')==='blob';}));$total=array_sum(array_map(function($x){return(int)($x['size']??0);},$files));$c=cfg();if(count($files)>$c['max_files']||$total>$c['max_total'])throw new RuntimeException('Repositorio excede limites.');$w=workspace($r);ensureDir($w);foreach($files as$e){$p=safePath($e['path']);$x=$gh->contents($p);$content=base64_decode(str_replace("\n",'',(string)($x['content']??'')),true);if($content===false)throw new RuntimeException('Falha ao obter '.$p);$dst=joinPath($w,$p);ensureDir(dirname($dst));if(file_put_contents($dst,$content,LOCK_EX)===false)throw new RuntimeException('Falha ao gravar '.$p);}rebuildState($r,$gh);$msg='Clone/atualizacao concluida: '.count($files).' arquivos.';
 }elseif($action==='local'){$r=sourceRepo();$data=statuses($r);
 }elseif($action==='edit'){$r=sourceRepo();$p=safePath((string)$_GET['path']);$f=joinPath(workspace($r),$p);if(!is_file($f)||filesize($f)>cfg()['max_file'])throw new RuntimeException('Arquivo inexistente ou grande demais.');$data=['path'=>$p,'content'=>(string)file_get_contents($f)];
 }elseif($action==='save'&&$_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$r=sourceRepo();$p=safePath((string)$_POST['path']);$f=joinPath(workspace($r),$p);ensureDir(dirname($f));if(is_file($f))copy($f,cfg()['storage'].DIRECTORY_SEPARATOR.'backups'.DIRECTORY_SEPARATOR.date('Ymd-His').'-'.str_replace('/','--',$p));if(file_put_contents($f,(string)$_POST['content'],LOCK_EX)===false)throw new RuntimeException('Falha ao salvar.');$msg='Arquivo salvo localmente.';$action='local';$data=statuses($r);
 }elseif($action==='newfile'&&$_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$r=sourceRepo();$p=safePath((string)$_POST['path']);$f=joinPath(workspace($r),$p);if(file_exists($f))throw new RuntimeException('Arquivo ja existe.');ensureDir(dirname($f));if(file_put_contents($f,(string)($_POST['content']??''),LOCK_EX)===false)throw new RuntimeException('Falha ao criar arquivo.');$msg='Novo arquivo criado no workspace.';$action='local';$data=statuses($r);
 }elseif($action==='newfolder'&&$_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$r=sourceRepo();$p=safePath((string)$_POST['path']);$d=joinPath(workspace($r),$p);if(file_exists($d))throw new RuntimeException('Pasta ja existe.');ensureDir($d);file_put_contents($d.DIRECTORY_SEPARATOR.'.gitkeep','',LOCK_EX);$msg='Pasta criada com .gitkeep.';$action='local';$data=statuses($r);
 }elseif($action==='upload'&&$_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$r=sourceRepo();if(!isset($_FILES['upload'])||$_FILES['upload']['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Falha no upload.');$dir=safePath((string)($_POST['directory']??''));$name=basename((string)$_FILES['upload']['name']);if($name===''||$name==='.'||$name==='..')throw new RuntimeException('Nome invalido.');$p=safePath(($dir===''?'':$dir.'/').$name);$dest=joinPath(workspace($r),$p);ensureDir(dirname($dest));if(!move_uploaded_file($_FILES['upload']['tmp_name'],$dest))throw new RuntimeException('Falha ao mover upload.');$msg='Upload salvo no workspace.';$action='local';$data=statuses($r);
 }elseif($action==='delete'&&$_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$r=sourceRepo();$p=safePath((string)$_POST['path']);$target=joinPath(workspace($r),$p);if(!file_exists($target))throw new RuntimeException('Item inexistente.');removeTree($target);$msg='Item removido localmente. O push confirmara a exclusao remota.';$action='local';$data=statuses($r);
 }elseif($action==='push'&&$_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$r=sourceRepo();if(($r['token']??'')===''&&($r['password']??'')==='')throw new RuntimeException('Token obrigatorio.');$message=trim((string)$_POST['message']);if($message==='')throw new RuntimeException('Mensagem obrigatoria.');$gh=new GH($r);$state=loadState($r);$ref=$gh->ref();$head=(string)($ref['object']['sha']??'');if(($state['base_commit']??'')!==$head)throw new RuntimeException('Conflito: o remoto mudou desde o clone. Clone/atualize antes de enviar.');$commit=$gh->commit($head);$baseTree=(string)($commit['tree']['sha']??'');if($baseTree==='')throw new RuntimeException('Base tree indisponivel.');$scan=scanFiles(workspace($r));$entries=[];$changed=0;$paths=array_unique(array_merge(array_keys($state['files']??[]),array_keys($scan['files'])));foreach($paths as$p){$old=$state['files'][$p]??null;$cur=$scan['files'][$p]??null;if($old!==null&&$cur===null){$entries[]=['path'=>$p,'mode'=>'100644','type'=>'blob','sha'=>null];$changed++;continue;}if($cur!==null&&($old===null||$cur['hash']!==($old['base_hash']??''))){$entries[]=['path'=>$p,'mode'=>'100644','type'=>'blob','sha'=>$gh->blob((string)file_get_contents($cur['file']))];$changed++;}}if($changed===0)throw new RuntimeException('Nenhuma alteracao para enviar.');$tree=$gh->createTree($baseTree,$entries);$newCommit=$gh->createCommit($message,$tree,$head);$gh->updateRef($newCommit);rebuildState($r,$gh);$msg='Push concluido em um unico commit: '.$changed.' alteracao(oes).';$action='local';$data=statuses($r);
 }
}catch(Throwable$e){$err=$e->getMessage();}
$r=$_SESSION['repo']??null;
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>WebGit API v4</title><style>body{font-family:Segoe UI,Arial,sans-serif;max-width:1180px;margin:28px auto;padding:0 18px;background:#f4f7fb;color:#172033}.card{background:#fff;border:1px solid #d8e0ea;border-radius:12px;padding:18px;margin:15px 0}.ok{color:#067647}.bad{color:#b42318}.warn{background:#fff4e5;padding:10px;border-left:4px solid #b54708}input,textarea{width:100%;padding:9px;margin:5px 0 12px;box-sizing:border-box}button{background:#175cd3;color:#fff;border:0;border-radius:7px;padding:9px 14px;cursor:pointer}.danger{background:#b42318}a{margin-right:12px}table{width:100%;border-collapse:collapse}td,th{padding:9px;border-bottom:1px solid #ddd;text-align:left}textarea{min-height:360px;font-family:Consolas,monospace}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:15px}</style></head><body><h1>WebGit via API</h1>
<?php if($msg):?><div class="card ok"><?=h($msg)?></div><?php endif;?><?php if($err):?><div class="card bad"><strong>Erro:</strong> <?=h($err)?></div><?php endif;?>
<?php if(!$r):?><div class="card"><h2>Conectar repositorio</h2><form method="post" action="?action=connect"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>URL HTTPS</label><input name="url" required><label>Branch</label><input name="branch" value="main" required><label>Usuario, opcional</label><input name="username"><label>Senha, opcional</label><input type="password" name="password"><label>Token</label><input type="password" name="token"><button>Conectar</button></form></div>
<?php else:?><div class="card"><strong><?=h($r['owner'].'/'.$r['repo'])?></strong> | <?=h($r['branch'])?><nav><a href="?">Inicio</a><a href="?action=browse">Remoto</a><a href="?action=local">Workspace/status</a><a href="?action=disconnect">Desconectar</a></nav></div><div class="card"><form method="post" action="?action=clone"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><button>Clonar/atualizar workspace</button></form></div>
<?php if($action==='browse'&&is_array($data)):?><div class="card"><h2>Conteudo remoto</h2><table><?php foreach($data as$x):?><tr><td><?=h($x['type']??'')?></td><td><?php if(($x['type']??'')==='dir'):?><a href="?action=browse&amp;path=<?=rawurlencode($x['path'])?>"><?=h($x['path'])?></a><?php else:?><?=h($x['path'])?><?php endif;?></td></tr><?php endforeach;?></table></div><?php endif;?>
<?php if($action==='local'&&is_array($data)):?><div class="card"><h2>Status local</h2><table><tr><th>Arquivo</th><th>Status</th><th>Tamanho</th><th>Acoes</th></tr><?php foreach($data as$x):?><tr><td><?=h($x['path'])?></td><td><?=h($x['status'])?></td><td><?=h($x['size'])?></td><td><?php if($x['status']!=='REMOVIDO'):?><a href="?action=edit&amp;path=<?=rawurlencode($x['path'])?>">Editar</a><form style="display:inline" method="post" action="?action=delete" onsubmit="return confirm('Excluir localmente?');"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="path" value="<?=h($x['path'])?>"><button class="danger">Excluir</button></form><?php endif;?></td></tr><?php endforeach;?></table></div>
<div class="grid"><div class="card"><h3>Novo arquivo</h3><form method="post" action="?action=newfile"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input name="path" placeholder="pasta/arquivo.txt" required><textarea name="content" placeholder="Conteudo inicial"></textarea><button>Criar arquivo</button></form></div><div class="card"><h3>Nova pasta</h3><form method="post" action="?action=newfolder"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input name="path" placeholder="pasta/subpasta" required><button>Criar pasta</button></form><h3>Upload</h3><form method="post" enctype="multipart/form-data" action="?action=upload"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input name="directory" placeholder="diretorio opcional"><input type="file" name="upload" required><button>Enviar ao workspace</button></form></div></div>
<div class="card"><h3>Push para o repositorio conectado</h3><p class="warn">Arquivos novos, alterados e removidos serao enviados em um unico commit. Se o remoto mudou, o push sera bloqueado.</p><form method="post" action="?action=push"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input name="message" placeholder="Mensagem do commit" required><button>Push das alteracoes</button></form></div><?php endif;?>
<?php if($action==='edit'&&is_array($data)):?><div class="card"><h2>Editar <?=h($data['path'])?></h2><form method="post" action="?action=save"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="path" value="<?=h($data['path'])?>"><textarea name="content"><?=h($data['content'])?></textarea><button>Salvar no workspace</button></form></div><?php endif;?>
<?php endif;?><div class="card"><strong>v4:</strong> cria arquivos e pastas, faz upload, edita, exclui e envia todas as mudancas em um unico commit pela API.</div></body></html>
